UPDATE orders
SET total_price = (
SELECT COALESCE(SUM(order_price), 0)
FROM order_details
WHERE order_id = #{orderId}
)
WHERE order_id = #{orderId}

mapper.select:
SELECT COUNT(*)
FROM order_details
WHERE order_id = #{orderId}

SELECT order_status
FROM order_details
WHERE order_id = #{orderId}

mapper.update:
UPDATE ingredients
SET supply_quantity = supply_quantity - #{orderQuantity}
WHERE ingredient_id = #{ingredientId}
AND supply_quantity >= #{orderQuantity}

UPDATE order_details od
JOIN orders o
ON o.order_id = od.order_id
SET
od.manufacture_at = #{manufactureAt},
od.store_at = #{storeAt}
WHERE od.order_detail_id = #{orderDetailId}
AND o.store_id = #{storeId}
AND od.order_status = '승인'
